-- GENERATED by scripts/gen-wave85-bank.ts (--wave116) from src/lib/questions/bank/*.ts.
-- Do not edit by hand. NOT APPLIED.
--
-- 17 questions had only two options (0.2 and 0.8). Each keeps those two,
-- in the same order, and gains a middle (0.5) plus a stronger end (0.95, or 0.05
-- when the less-flattering side is the low end). The unflattering tag is unchanged.
-- An answer already given still points at the same option index. No answer row moves.

-- The bank allowed 2 or 3 options. Four is the new ceiling.
do $bounds$
declare
  r record;
begin
  for r in
    select conname
      from pg_constraint
     where conrelid = 'public.question_bank'::regclass
       and contype = 'c'
       and pg_get_constraintdef(oid) like '%jsonb_array_length(options)%'
  loop
    execute format('alter table public.question_bank drop constraint %I', r.conname);
  end loop;
end
$bounds$;

alter table public.question_bank
  add constraint question_bank_options_len
  check (jsonb_typeof(options) = 'array' and jsonb_array_length(options) between 2 and 4);

